<template>
  <AppLoader v-if="isLoading && !projectVoterDatabase" subject="voter database" />
  <AppError v-else-if="error" :error="error" title="Failed to load project voter database" />
  <div v-else-if="projectVoterDatabase" class="grid grid-cols-8">
    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Voter Database</CardTitle>
      </CardHeader>
      <CardContent class="flex flex-col">
        <ProjectEditFormVdbUpload v-if="!status" :database-name="projectVoterDatabase.database_name" />
        <ProjectEditFormVdbProcessing
          v-else-if="status === 'pending' || status === 'processing' || status === 'indexing' || status === 'geocoding'"
          :status="status"
        />
        <State
          v-else-if="status === 'failed'"
          title="Failed to import data"
          :description="projectVoterDatabase.error_message"
          :icon="AlertOctagon"
          icon-class="stroke-destructive size-16 w-16"
        >
          <ProjectEditFormVdbUploadNew />
        </State>
        <ProjectEditFormVdbImported
          v-if="status === 'imported' || status === 'geocoding'"
          :name="projectVoterDatabase.database_name"
          :uploaded-at="projectVoterDatabase.created_at"
          :s3-url="projectVoterDatabase.file_url"
          :file-name="projectVoterDatabase.file_name"
          :table="projectVoterDatabase.table_data"
          :headers="projectVoterDatabase.table_columns"
        />
        <template v-else-if="status === 'removed'">
          <State title="Project is finished" description="Data was removed" class="py-10">
            <ProjectEditFormVdbUploadNew />
          </State>
        </template>
      </CardContent>
    </Card>
  </div>
</template>

<script lang="ts" setup>
import { useProjectVoterDatabase } from '~/queries/project/edit/voterDatabase';
import { AlertOctagon } from 'lucide-vue-next';

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

useSeoMeta({
  title: computed(() => 'Edit Project'),
  description: computed(() => 'Edit your project voter database here.'),
});

const { projectVoterDatabase, isLoading, error, status } = useProjectVoterDatabase();
</script>

<style lang="scss" scoped></style>
