<template>
  <form id="project-edit-vdb-upload" class="w-full flex flex-col gap-6" @submit="onSubmit">
    <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
      <FormItemWrapper name="database_name" label="Database Name">
        <template #default="{ slots }">
          <Input id="database_name" type="text" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
      <FormItemWrapper name="s3_url">
        <template #default="{ slots }">
          <KitFormFileUpload
            form-id="project-edit-vdb-file-upload"
            :file-types="['.csv']"
            :file-size-limit="15"
            size-unit="GB"
            @on-process-data="
              (value) => {
                if (value) {
                  slots.setValue(value.privateUrl, false);
                  setFieldValue('file_name', value.fileName, false);
                  s3Url = value.privateUrl;
                } else {
                  slots.setValue(undefined, false);
                  setFieldValue('file_name', undefined, false);
                  s3Url = '';
                }
              }
            "
          />
        </template>
      </FormItemWrapper>
      <AppLoader v-if="isLoading" class="md:col-span-2" variant="inline" subject="voter database" />
      <AppError v-else-if="error" class="md:col-span-2" title="Failed to load columns mapping" :error="error" />
      <div v-else-if="s3Url && columnMapping" class="flex flex-col gap-2 md:col-span-2">
        <span>Columns Mapping</span>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">
          <FormItemWrapper name="state_voter_id">
            <template #default="{ slots }">
              <div class="grid grid-cols-2 items-center gap-2">
                <label for="state_voter_id" class="text-sm font-medium text-nowrap"> State Voter ID </label>
                <KitFormsSelect
                  id="state_voter_id"
                  :items="mappingSelectItems"
                  :component-field="slots.componentField"
                  @vue:mounted="() => slots.setValue(columnMapping?.predicted_mapping['state_voter_id'], false)"
                />
              </div>
            </template>
          </FormItemWrapper>
          <Separator class="md:col-span-full" />
          <FormItemWrapper name="multiple_regions">
            <template #default="{ slots }">
              <div class="grid grid-cols-2 items-center gap-2 h-10">
                <label for="multiple_regions" class="text-sm font-medium text-nowrap">Multiple Regions</label>
                <Switch
                  id="multiple_regions"
                  :model-value="slots.value"
                  @update:model-value="slots.handleChange"
                  @vue:mounted="
                    () => {
                      if (columnMapping) slots.setValue(columnMapping['multiple_regions'], false);
                    }
                  "
                />
              </div>
            </template>
          </FormItemWrapper>
          <FormItemWrapper v-if="values.multiple_regions" name="region">
            <template #default="{ slots }">
              <div class="grid grid-cols-2 items-center gap-2">
                <label for="region" class="text-sm font-medium text-nowrap">Region</label>
                <KitFormsSelect
                  id="region"
                  :items="mappingSelectItems"
                  :component-field="slots.componentField"
                  @vue:mounted="() => slots.setValue(columnMapping?.predicted_mapping['region'], false)"
                />
              </div>
            </template>
          </FormItemWrapper>
          <Separator class="md:col-span-full" />
          <FormItemWrapper name="contains_mailing_address">
            <template #default="{ slots }">
              <div class="grid grid-cols-2 items-center gap-2 h-10">
                <label for="contains_mailing_address" class="text-sm font-medium text-nowrap"
                  >Contains Mailing Address</label
                >
                <Switch
                  id="contains_mailing_address"
                  :model-value="slots.value"
                  @update:model-value="slots.handleChange"
                  @vue:mounted="
                    () => {
                      if (columnMapping) slots.setValue(columnMapping['contains_mailing_address'], false);
                    }
                  "
                />
              </div>
            </template>
          </FormItemWrapper>
        </div>
      </div>
    </div>
    <div class="flex justify-end">
      <Button
        type="submit"
        form="project-edit-vdb-upload"
        :disabled="!s3Url || !columnMapping || !values.database_name || !values.s3_url"
        :loading="isUploadingProjectVoterDatabaseLoading"
        >Upload</Button
      >
    </div>
  </form>
</template>

<script lang="ts" setup>
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { useUploadProjectVoterDatabase } from '~/mutations/project/edit/uploadVoterDatabase';
import { useCsvColumnMapping } from '~/queries/project/edit/csvColumnMapping';

interface Props {
  databaseName?: string | null;
}

const props = defineProps<Props>();

const { uploadProjectVoterDatabase, isUploadingProjectVoterDatabaseLoading } = useUploadProjectVoterDatabase();
const { s3Url, columnMapping, isLoading, error } = useCsvColumnMapping();

const inputSchema = toTypedSchema(
  z.object({
    database_name: z
      .string({ message: 'Database Name is required' })
      .trim()
      .nonempty('Database Name is required')
      .max(255, 'Database Name must be less than 255 characters'),
    s3_url: z.string({ message: 'CSV file is required' }).nonempty('CSV file is required'),
    file_name: z.string().optional(),
    state_voter_id: z.string({ message: 'State Voter ID is required' }).nonempty('State Voter ID is required'),
    multiple_regions: z.boolean().default(false),
    region: z
      .string({ message: 'Region is required' })
      .optional()
      .refine((val) => {
        if (!values.multiple_regions) return true;
        else return val && val.trim().length > 0;
      }),
    contains_mailing_address: z.boolean().default(false),
  })
);

const { handleSubmit, setFieldValue, values } = useForm({
  validationSchema: inputSchema,
});

const onSubmit = handleSubmit(async (values) => {
  const projectId = useRoute('projects-id-edit-voter-database').params.id as string;
  const requestData = {
    database_name: values.database_name,
    s3_url: values.s3_url,
    file_name: values.file_name || '',
    columns_mapping: {
      state_voter_id: values.state_voter_id,
      ...(values.multiple_regions &&
        columnMapping.value && {
          region: values.region,
        }),
    },
    multiple_regions: values.multiple_regions,
    contains_mailing_address: values.contains_mailing_address,
  };
  await uploadProjectVoterDatabase({
    data: requestData,
    projectId: projectId,
  });
});

onMounted(() => {
  setFieldValue('database_name', props.databaseName || '', false);
});

onUnmounted(() => {
  s3Url.value = '';
});

const mappingSelectItems = computed<SelectItem[]>(() => {
  return (
    columnMapping.value?.fields.map((field) => ({
      name: field,
      value: field,
    })) || []
  );
});
</script>

<style lang="scss" scoped></style>
