import { getVoterDatabaseColumnsMapping } from '~/client';

export const useCsvColumnMapping = defineQuery(() => {
  const s3Url = ref<string>('');

  const {
    data: columnMapping,
    error,
    isLoading,
  } = useQuery({
    key: () => ['project-csv-column-mapping', s3Url.value],
    query: () => getVoterDatabaseColumnsMapping({ composable: '$fetch', query: { s3_url: s3Url.value } }),
    staleTime: 0,
    enabled: () => useRoute().name === 'projects-id-edit-voter-database' && !!s3Url.value,
  });

  return {
    s3Url,
    columnMapping,
    error,
    isLoading,
  };
});
