import { editProjectVoterDatabase } from '~/client';
import type { EditProjectVoterDatabaseResponse, EditProjectVoterDatabaseRequest } from '~/client';

export const useUploadProjectVoterDatabase = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      data: EditProjectVoterDatabaseRequest;
      projectId: string;
    }): Promise<EditProjectVoterDatabaseResponse> =>
      editProjectVoterDatabase({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: params.data,
      }),
    onSuccess: (data, params) => {
      const queryCache = useQueryCache();
      queryCache.setQueryData(['project-voter-database', params.projectId], () => {
        return {
          status: data.status,
        };
      });
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      showToastSuccess(`CSV file uploaded for processing successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    uploadProjectVoterDatabase: mutateAsync,
    isUploadingProjectVoterDatabaseLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
