<template>
  <Button class="w-fit" :prepend-icon="UploadIcon" @click="onUploadNewFileClick">Upload New File</Button>
</template>

<script lang="ts" setup>
import type { GetProjectVoterDatabaseConfigurationResponse } from '~/client';
import { UploadIcon } from 'lucide-vue-next';
import { useCsvColumnMapping } from '~/queries/project/edit/csvColumnMapping';

const { s3Url } = useCsvColumnMapping();

function onUploadNewFileClick() {
  s3Url.value = '';
  const queryCache = useQueryCache();
  const projectId = useRoute('projects-id-edit-voter-database').params.id as string;
  queryCache.setQueryData(
    ['project-voter-database', projectId],
    (data: GetProjectVoterDatabaseConfigurationResponse | undefined) => {
      return {
        status: null,
        database_name: data?.database_name ?? null,
      };
    }
  );
}
</script>

<style lang="scss" scoped />
